async () => {
const g=document.querySelector('vaadin-grid');
const seen=new Map();
for(let i=0;i<200;i++){
 g._getVisibleRows?.().forEach(r=>{const it=r._item; if(it) seen.set(it.id??JSON.stringify(it),it)});
 const before=g.scrollTop; g.scrollTop+=400; await new Promise(r=>setTimeout(r,150));
 if(i>3&&g.scrollTop===before)break;
}
const items=[...seen.values()];
return {n:items.length, sample:items[0], count:items.filter(x=>x.company?.name?.startsWith('Linens')&&x.status?.name==='Imported lead'||(x.company==="Linens 'n Things Inc."&&x.status==='Imported lead')).length};
}

