async () => {
const g=document.querySelector('vaadin-grid');
const seen=new Map();
const sc=g.shadowRoot.querySelector('#table');
for(let i=0;i<300;i++){
 g.querySelectorAll('vaadin-grid-cell-content').forEach(c=>{});
 const rows=[...g.shadowRoot.querySelectorAll('tr')].filter(r=>r.querySelector('td'));
 rows.forEach(r=>{const t=[...r.querySelectorAll('td')].map(td=>{const s=td.querySelector('slot');return s?s.assignedNodes()[0]?.textContent:''});if(t[0])seen.set(t[2],t)});
 const b=sc.scrollTop; sc.scrollTop+=300; await new Promise(r=>setTimeout(r,120));
 if(i>3&&sc.scrollTop===b)break;
}
const a=[...seen.values()];
return {n:a.length,c:a.filter(t=>t[4]?.trim()==="Linens 'n Things Inc."&&t[3]?.trim()==='Imported lead').length};
}

